from sympy import I, sqrt, symbols, expand, factor, Poly
x, y, z = symbols('x y z')
original = expand((x - 1)*(y - 1))
print('Reported example:', factor(original, extension=[I]))
cases = [
    (x - 1)*(y - 1),
    3*(x - 1)**2*(y - 1)**3,
    (x**2 + 1)*(y**2 + 1),
    (x - y)*(y - z)**2*(z**2 - 2),
    (1 + I)*(x + I*y)**2*(y - I)**3,
    (y - 1)**3*(z**2 + 1),
    (x*y + 1)*(y**2 - 2),
]
checks = 0
for extension in ([I], [sqrt(2)], [I, sqrt(2)], True):
    for expression in cases:
        result = factor(expand(expression), extension=extension)
        assert expand(result - expression) == 0, (expression, extension, result)
        checks += 1
for expression in cases:
    p = Poly(expression, x, y, z, extension=[I, sqrt(2)])
    coefficient, factors = p.factor_list()
    product = Poly(coefficient, x, y, z, domain=p.domain)
    for f, multiplicity in factors:
        product *= f**multiplicity
    assert product == p
    checks += 1
print('Reconstruction checks passed:', checks)
PY
